import java.util.*;
import java.lang.*;
import java.io.*;

class Codechef
{
    static final long Mod = 998244353L;
    static final int MaxN = 200000;
    static long[] inv = new long[MaxN + 1];
    static long[] H = new long[MaxN + 1];
    
    static void precompute(){
        inv[1] = 1;
        for(int i=2; i<= MaxN; i++){
            inv[i] = Mod-(Mod/i)*inv[(int)(Mod%i)]%Mod;
        }
        H[0] = 0;
        for(int i=1; i<= MaxN; i++){
            H[i] = (H[i-1]+inv[i])%Mod;
        }
    }
    
    static void solve(FastScanner fs, StringBuilder out) throws Exception{
        int n = fs.nextInt();
        long[] a = new long[n];
        
        for(int i=0; i<n; i++){
            a[i] = fs.nextLong() % Mod;
            if(a[i] < 0)a[i] += Mod;
        }
        
        long ans = 0;
        for(int i=0; i<n; i++){
            long coeff = (H[i] + H[n-i-1])%Mod;
            
            ans = (ans + a[i] * coeff)%Mod;
        }
        out.append(ans).append("\n");
    }
	public static void main (String[] args) throws Exception
	{
	    FastScanner fs = new FastScanner(System.in);
	    StringBuilder out = new StringBuilder();
	    
	    precompute();
	    int t = fs.nextInt();
	    while(t -- > 0){
	        solve(fs, out);
	    }
	    System.out.print(out);
		// your code goes here

	}
	static class FastScanner{
	    private final InputStream in;
	     private final byte[] buffer = new byte[1<<16];
	     private int ptr = 0, len=0;
	     
	     FastScanner(InputStream is){
	         in = is;
	     }
	     private int read() throws IOException{
	         if(ptr >= len){
	             len = in.read(buffer);
	             ptr = 0;
	             if(len <=0){
	                 return -1;
	                 
	             }
	         }
	         return buffer[ptr++];
	     }
	     long nextLong() throws IOException{
	         int c;
	         do{
	             c = read();
	         }while(c<=' ');
	         boolean neg = false;
	         if(c=='-'){
	             neg=true;
	             c=read();
	             
	         }
	         long result=0;
	         while(c>' '){
	             result=result*10+(c-'0');
	             c=read();
	         }
	         return neg? -result : result;
	     }
	     int nextInt() throws IOException{
	         return (int) nextLong();
	     }
	}
}
